-- Activities and events: sports, competitions, clubs, cultural, awards, communication, houses, event management.
CREATE TABLE public.act_sports (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, venue VARCHAR(80) NOT NULL DEFAULT '', teams VARCHAR(160) NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.act_teams (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, sport VARCHAR(80) NOT NULL, team VARCHAR(80) NOT NULL, coach VARCHAR(80) NOT NULL DEFAULT '', players INTEGER NOT NULL DEFAULT 0 CHECK (players >= 0), practice VARCHAR(80) NOT NULL DEFAULT '', status VARCHAR(10) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Inactive')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.act_competitions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(120) NOT NULL, level VARCHAR(12) NOT NULL CHECK (level IN ('School', 'Inter-school', 'District', 'State', 'National')), comp_date DATE NOT NULL, registered INTEGER NOT NULL DEFAULT 0 CHECK (registered >= 0), result VARCHAR(40) NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL DEFAULT 'Registrations open' CHECK (status IN ('Registrations open', 'Results awaited', 'Completed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.act_clubs (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, teacher VARCHAR(80) NOT NULL DEFAULT '', members INTEGER NOT NULL DEFAULT 0 CHECK (members >= 0), meets VARCHAR(60) NOT NULL DEFAULT '', status VARCHAR(10) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Inactive')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.act_cultural (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, what VARCHAR(160) NOT NULL DEFAULT '', days VARCHAR(60) NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.act_participation (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, event VARCHAR(120) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Registrations open', students INTEGER NOT NULL DEFAULT 0 CHECK (students >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.act_awards (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, award VARCHAR(120) NOT NULL, given_to VARCHAR(80) NOT NULL, a_type VARCHAR(14) NOT NULL CHECK (a_type IN ('Student award', 'Staff award')), class_dept VARCHAR(60) NOT NULL DEFAULT '', award_date DATE NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'Announced' CHECK (status IN ('Announced', 'Presented')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.act_comms (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, kind VARCHAR(10) NOT NULL CHECK (kind IN ('Invitation', 'Notice')), title VARCHAR(160) NOT NULL, sent_to VARCHAR(80) NOT NULL, comm_date DATE NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft', 'Live')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.act_houses (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(40) NOT NULL, UNIQUE (institution_id, name));
CREATE TABLE public.act_house_points (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, house_id UUID NOT NULL REFERENCES public.act_houses(id) ON DELETE CASCADE, student_id UUID REFERENCES public.students(id) ON DELETE SET NULL, student_label VARCHAR(100) NOT NULL DEFAULT '', points INTEGER NOT NULL CHECK (points BETWEEN 1 AND 100), reason VARCHAR(160) NOT NULL, awarded_by VARCHAR(80) NOT NULL DEFAULT '', awarded_on DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE public.event_mgmt (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, event_date DATE NOT NULL, for_label VARCHAR(60) NOT NULL DEFAULT 'Whole school', etype VARCHAR(12) NOT NULL DEFAULT 'Celebration' CHECK (etype IN ('Celebration', 'Trip', 'Sports', 'Competition', 'Other')), join_mode VARCHAR(40) NOT NULL DEFAULT 'Parents RSVP', registered INTEGER NOT NULL DEFAULT 0 CHECK (registered >= 0), capacity INTEGER CHECK (capacity >= 0), fees_collected INTEGER NOT NULL DEFAULT 0 CHECK (fees_collected >= 0), budget INTEGER NOT NULL DEFAULT 0 CHECK (budget >= 0), spent INTEGER NOT NULL DEFAULT 0 CHECK (spent >= 0), in_charge VARCHAR(80) NOT NULL DEFAULT '', attended INTEGER CHECK (attended >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.event_volunteers (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, event_id UUID NOT NULL REFERENCES public.event_mgmt(id) ON DELETE CASCADE, name VARCHAR(80) NOT NULL, student_label VARCHAR(80) NOT NULL DEFAULT '', role VARCHAR(80) NOT NULL, time_label VARCHAR(40) NOT NULL DEFAULT '', status VARCHAR(10) NOT NULL DEFAULT 'Requested' CHECK (status IN ('Requested', 'Confirmed')));
CREATE TABLE public.event_duties (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, event_id UUID NOT NULL REFERENCES public.event_mgmt(id) ON DELETE CASCADE, staff_name VARCHAR(80) NOT NULL, duty VARCHAR(80) NOT NULL, time_label VARCHAR(40) NOT NULL DEFAULT '');
ALTER TABLE public.act_sports ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_teams ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_competitions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_clubs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_cultural ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_participation ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_awards ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_comms ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_houses ENABLE ROW LEVEL SECURITY; ALTER TABLE public.act_house_points ENABLE ROW LEVEL SECURITY; ALTER TABLE public.event_mgmt ENABLE ROW LEVEL SECURITY; ALTER TABLE public.event_volunteers ENABLE ROW LEVEL SECURITY; ALTER TABLE public.event_duties ENABLE ROW LEVEL SECURITY;
